import{_ as l,a0 as o,w as d,s as r,ao as t,I as p,x as n,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何把 awk 腳本移植到 Python | LCTT x X-CMD","titleTemplate":false,"description":"如何把 awk 腳本移植到 Python | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何把 awk 腳本移植到 Python | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何把 awk 腳本移植到 Python | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191115 How to port an awk script to Python","title":"如何把 awk 腳本移植到 Python","tag":"201912","desc":""},"relativePath":"201912/20191115 How to port an awk script to Python.md","filePath":"[post].md"}'),h={name:"201912/20191115 How to port an awk script to Python.md"};function k(c,s,f,g,u,y){const a=o("Link");return d(),r("div",null,[s[21]||(s[21]=t(`<h1 id="如何把-awk-腳本移植到-python" tabindex="-1">如何把 awk 腳本移植到 Python <a class="header-anchor" href="#如何把-awk-腳本移植到-python" aria-label="Permalink to “如何把 awk 腳本移植到 Python”">​</a></h1><blockquote><p>將一個 awk 腳本移植到 Python 主要在於代碼風格而不是轉譯。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201912/08/095256ko6xdfwooe8zctfz.jpg" alt=""></p><p>腳本是解決問題的有效方法，而 awk 是編寫腳本的出色語言。它特別擅長於簡單的文本處理，它可以帶你完成配置文件的某些複雜重寫或目錄中文件名的重新格式化。</p><h3 id="何時從-awk-轉向-python" tabindex="-1">何時從 awk 轉向 Python <a class="header-anchor" href="#何時從-awk-轉向-python" aria-label="Permalink to “何時從 awk 轉向 Python”">​</a></h3><p>但是在某些方面，awk 的限制開始顯現出來。它沒有將文件分解為模組的真正概念，它缺乏質量錯誤報告，並且缺少了現在被認為是編程語言工作原理的其他內容。當編程語言的這些豐富功能有助於維護關鍵腳本時，移植將是一個不錯的選擇。</p><p>我最喜歡的完美移植 awk 的現代編程語言是 Python。</p><p>在將 awk 腳本移植到 Python 之前，通常值得考慮一下其原始使用場景。例如，由於 awk 的侷限性，通常從 Bash 腳本調用 awk 代碼，其中包括一些對 <code>sed</code>、<code>sort</code> 之類的其它命令列常見工具的調用。 最好將所有內容轉換為一個一致的 Python 程序。有時，腳本會做出過於寬泛的假設，例如，即使實際上只運行一個文件，該代碼也可能允許任意數量的文件。</p><p>在仔細考慮了上下文並確定了要用 Python 替代的東西之後，該編寫代碼了。</p><h3 id="標準-awk-到-python-功能" tabindex="-1">標準 awk 到 Python 功能 <a class="header-anchor" href="#標準-awk-到-python-功能" aria-label="Permalink to “標準 awk 到 Python 功能”">​</a></h3><p>以下 Python 功能是有用的，需要記住：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(some_file_name) as fpin:</span></span>
<span class="line"><span>    for line in fpin:</span></span>
<span class="line"><span>        pass # do something with line</span></span></code></pre></div><p>此代碼將逐行循環遍歷文件並處理這些行。</p><p>如果要訪問行號（相當於 awk 的 <code>NR</code>），則可以使用以下代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(some_file_name) as fpin:</span></span>
<span class="line"><span>    for nr, line in enumerate(fpin):</span></span>
<span class="line"><span>        pass # do something with line</span></span></code></pre></div><h3 id="在-python-中實現多文件的-awk-式行為" tabindex="-1">在 Python 中實現多文件的 awk 式行為 <a class="header-anchor" href="#在-python-中實現多文件的-awk-式行為" aria-label="Permalink to “在 Python 中實現多文件的 awk 式行為”">​</a></h3><p>如果你需要能夠遍歷任意數量的文件同時保持行數的持續計數（類似 awk 的 <code>FNR</code>），則此循環可以做到這一點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def awk_like_lines(list_of_file_names):</span></span>
<span class="line"><span>    def _all_lines():</span></span>
<span class="line"><span>        for filename in list_of_file_names:</span></span>
<span class="line"><span>            with open(filename) as fpin:</span></span>
<span class="line"><span>                yield from fpin</span></span>
<span class="line"><span>    yield from enumerate(_all_lines())</span></span></code></pre></div><p>此語法使用 Python 的<em>生成器</em>和 <code>yield from</code> 來構建<em>迭代器</em>，該迭代器將遍歷所有行並保持一個持久計數。</p><p>如果你需要同時使用 <code>FNR</code> 和 <code>NR</code>，這是一個更復雜的循環：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def awk_like_lines(list_of_file_names):</span></span>
<span class="line"><span>    def _all_lines():</span></span>
<span class="line"><span>        for filename in list_of_file_names:</span></span>
<span class="line"><span>            with open(filename) as fpin:</span></span>
<span class="line"><span>                yield from enumerate(fpin)</span></span>
<span class="line"><span>    for nr, (fnr, line) in _all_lines:</span></span>
<span class="line"><span>        yield nr, fnr, line</span></span></code></pre></div><h3 id="更復雜的-fnr、nr-和行數的-awk-行為" tabindex="-1">更復雜的 FNR、NR 和行數的 awk 行為 <a class="header-anchor" href="#更復雜的-fnr、nr-和行數的-awk-行為" aria-label="Permalink to “更復雜的 FNR、NR 和行數的 awk 行為”">​</a></h3><p>如果 <code>FNR</code>、<code>NR</code> 和行數這三個你全都需要，仍然會有一些問題。如果確實如此，則使用三元組（其中兩個項目是數字）會導致混淆。命名參數可使該代碼更易於閲讀，因此最好使用 <code>dataclass</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import dataclass</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@dataclass.dataclass(frozen=True)</span></span>
<span class="line"><span>class AwkLikeLine:</span></span>
<span class="line"><span>    content: str</span></span>
<span class="line"><span>    fnr: int</span></span>
<span class="line"><span>    nr: int</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def awk_like_lines(list_of_file_names):</span></span>
<span class="line"><span>    def _all_lines():</span></span>
<span class="line"><span>        for filename in list_of_file_names:</span></span>
<span class="line"><span>            with open(filename) as fpin:</span></span>
<span class="line"><span>                yield from enumerate(fpin)</span></span>
<span class="line"><span>    for nr, (fnr, line) in _all_lines:</span></span>
<span class="line"><span>        yield AwkLikeLine(nr=nr, fnr=fnr, line=line)</span></span></code></pre></div><p>你可能想知道，為什麼不一直用這種方法呢？使用其它方式的的原因是總用這種方法太複雜了。如果你的目標是把一個通用庫更容易地從 awk 移植到 Python，請考慮這樣做。但是編寫一個可以使你確切地瞭解特定情況所需的循環的方法通常更容易實現，也更容易理解（因而易於維護）。</p><h3 id="理解-awk-字段" tabindex="-1">理解 awk 字段 <a class="header-anchor" href="#理解-awk-字段" aria-label="Permalink to “理解 awk 字段”">​</a></h3><p>一旦有了與一行相對應的字符串，如果要轉換 awk 程序，則通常需要將其分解為<em>字段</em>。Python 有幾種方法可以做到這一點。這將把行按任意數量的連續空格拆分，返回一個字符串列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line.split()</span></span></code></pre></div><p>如果需要另一個字段分隔符，比如以 <code>:</code> 分隔行，則需要 <code>rstrip</code> 方法來刪除最後一個換行符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line.rstrip(&quot;\\n&quot;).split(&quot;:&quot;)</span></span></code></pre></div><p>完成以下操作後，列表 <code>parts</code> 將存有分解的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>parts = line.rstrip(&quot;\\n&quot;).split(&quot;:&quot;)</span></span></code></pre></div>`,32)),p("p",null,[s[1]||(s[1]=n("這種拆分非常適合用來處理參數，但是我們處於",-1)),i(a,{href:"https://en.wikipedia.org/wiki/Off-by-one_error"},{default:e(()=>[...s[0]||(s[0]=[n("偏差一個的錯誤",-1)])]),_:1}),s[2]||(s[2]=t("場景中。現在 <code>parts[0]</code> 將對應於 awk 的 <code>$1</code>，<code>parts[1]</code> 將對應於 awk 的 <code>$2</code>，依此類推。之所以偏差一個，是因為 awk 計數“字段”從 1 開始，而 Python 從 0 開始計數。在 awk 中，<code>$0</code> 是整個行 —— 等同於 <code>line.rstrip(&quot;\\n&quot;)</code>，而 awk 的 <code>NF</code>（字段數）更容易以 <code>len(parts)</code> 的形式得到。",17))]),s[22]||(s[22]=p("h3",{id:"移植-awk-字段到-python",tabindex:"-1"},[n("移植 awk 字段到 Python "),p("a",{class:"header-anchor",href:"#移植-awk-字段到-python","aria-label":"Permalink to “移植 awk 字段到 Python”"},"​")],-1)),p("p",null,[s[4]||(s[4]=n("例如，讓我們將這個單行代碼“",-1)),i(a,{href:"https://opensource.com/article/19/10/remove-duplicate-lines-files-awk"},{default:e(()=>[...s[3]||(s[3]=[n("如何使用 awk 從文件中刪除重複行",-1)])]),_:1}),s[5]||(s[5]=n("”轉換為 Python。",-1))]),s[23]||(s[23]=t(`<p><code>awk</code> 中的原始代碼是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39;!visited[$0]++&#39; your_file &gt; deduplicated_file</span></span></code></pre></div><p>“真實的” Python 轉換將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import collections</span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>visited = collections.defaultdict(int)</span></span>
<span class="line"><span>for line in open(&quot;your_file&quot;):</span></span>
<span class="line"><span>    did_visit = visited[line]</span></span>
<span class="line"><span>    visited[line] += 1</span></span>
<span class="line"><span>    if not did_visit:</span></span>
<span class="line"><span>        sys.stdout.write(line)</span></span></code></pre></div><p>但是，Python 比 awk 具有更多的數據結構。與其計數訪問次數（除了知道是否看到一行，我們不使用它），為什麼不記錄訪問的行呢？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>visited = set()</span></span>
<span class="line"><span>for line in open(&quot;your_file&quot;):</span></span>
<span class="line"><span>    if line in visited:</span></span>
<span class="line"><span>        continue</span></span>
<span class="line"><span>    visited.add(line)</span></span>
<span class="line"><span>    sys.stdout.write(line)</span></span></code></pre></div><h3 id="編寫-python-化的-awk-代碼" tabindex="-1">編寫 Python 化的 awk 代碼 <a class="header-anchor" href="#編寫-python-化的-awk-代碼" aria-label="Permalink to “編寫 Python 化的 awk 代碼”">​</a></h3><p>Python 社區提倡編寫 Python 化的代碼，這意味着它要遵循公認的代碼風格。更加 Python 化的方法將區分<em>唯一性</em>和輸入/輸出的關注點。此更改將使對代碼進行單元測試更加容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def unique_generator(things):</span></span>
<span class="line"><span>    visited = set()</span></span>
<span class="line"><span>    for thing in things:</span></span>
<span class="line"><span>        if thing in visited:</span></span>
<span class="line"><span>            continue</span></span>
<span class="line"><span>        visited.add(things)</span></span>
<span class="line"><span>        yield thing</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>for line in unique_generator(open(&quot;your_file&quot;)):</span></span>
<span class="line"><span>    sys.stdout.write(line)</span></span></code></pre></div><p>將所有邏輯置於輸入/輸出代碼之外，可以更好地分離問題，並提高代碼的可用性和可測試性。</p><h3 id="結論-python-可能是一個不錯的選擇" tabindex="-1">結論：Python 可能是一個不錯的選擇 <a class="header-anchor" href="#結論-python-可能是一個不錯的選擇" aria-label="Permalink to “結論：Python 可能是一個不錯的選擇”">​</a></h3><p>將 awk 腳本移植到 Python 時，通常是在考慮適當的 Python 代碼風格時重新實現核心需求，而不是按條件/操作進行笨拙的音譯。考慮原始上下文併產生高質量的 Python 解決方案。雖然有時候使用 awk 的 Bash 單行代碼可以完成這項工作，但 Python 編碼是通往更易於維護的代碼的途徑。</p><p>另外，如果你正在編寫 awk 腳本，我相信您也可以學習 Python！如果你有任何疑問，請告訴我。</p><hr>`,14)),p("p",null,[s[7]||(s[7]=n("via: ",-1)),i(a,{href:"https://opensource.com/article/19/11/awk-to-python"},{default:e(()=>[...s[6]||(s[6]=[n("https://opensource.com/article/19/11/awk-to-python",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("作者：",-1)),i(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[8]||(s[8]=[n("Moshe Zadka",-1)])]),_:1}),s[13]||(s[13]=n(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[9]||(s[9]=[n("lujun9972",-1)])]),_:1}),s[14]||(s[14]=n(" 譯者：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1}),s[15]||(s[15]=n(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[18]||(s[18]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[16]||(s[16]=[n("LCTT",-1)])]),_:1}),s[19]||(s[19]=n(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[17]||(s[17]=[n("Linux中國",-1)])]),_:1}),s[20]||(s[20]=n(" 榮譽推出",-1))])])}const _=l(h,[["render",k]]);export{m as __pageData,_ as default};
